/* 第01轮当前生效入口。此文件在 production UI 后加载，捕获旧漫画转动画入口。 */
(()=>{
  const C=Cimora,{S,M,E,art,link,path,money}=C,A=M.adaptation,P=M.production;
  const B=(text,action,extra='',cls='cm-button ghost')=>`<button type="button" class="${cls}" data-adapt="${action}" ${extra}>${text}</button>`;
  const repaint=()=>S.render(),editable=c=>{if(c.e.run&&['running','paused'].includes(c.e.run.status)){S.toast('请先停止当前制作批次');return false;}return true;};
  const refsText=(c,s)=>(s.sources||[]).map(r=>{const ch=c.p.chapters.find(x=>x.id===r.chapterId),b=ch&&M.ensure(c.p,ch).boards.find(x=>x.id===r.panelId);return `${ch?.title||'已移除章节'} / ${b?'第 '+(M.ensure(c.p,ch).boards.indexOf(b)+1)+' 格':'已移除分格'} · 来源 v${r.version}`;}).join('；')||'独立镜头 · 无漫画来源';
  const sourceLinks=(c,s)=>(s.sources||[]).map(r=>link(E(refsText(c,{sources:[r]})),path({p:c.p,c:{id:r.chapterId}},'boards')+'&panel='+r.panelId,'cm-text-link')+(r.snapshot.comicSource&&C.comicSourceDetails?'<details><summary>已引用漫画资料 · 无字底图与文字归属</summary>'+C.comicSourceDetails(r.snapshot)+'</details>':'')).join('<br>')||'<small>独立镜头 · 无漫画来源</small>';
  function rangeNotice(c){if(c.e.importDraft)return '';const r=A.range(c);if(!r.total)return '';return `<section class="cm-notice ad-text-range"><strong>原文 ${r.total} 句 · 已整理前 ${r.done} 句 · 剩余 ${r.remaining} 句</strong><p>${r.remaining?'下一批：第 '+r.nextStart+'–'+r.nextEnd+' 句（每批最多24句）；只续接后段，不重做已有镜头或分格。':'当前原文已全部整理；不会重复追加相同范围。'}${r.changed?' 原文有修改，当前范围按能识别的连续前缀计算，请核对下方内容。':''}${r.legacy?' 已从旧草案识别覆盖范围，既有ID与候选保持。':''}</p>${r.remaining?B('继续整理剩余 '+r.remaining+' 句','draft','','cm-button primary small'):''}</section>`;}
  function importPending(c){const d=c.e.importDraft;return `<section class="cm-panel"><span class="cm-kicker">COMIC IMPORT</span><h2>漫画已登记，等待解析。</h2><p>目标：${d.target==='comic'?'漫画整理':'漫画 → 视频'}。尚未生成分格或动画镜头。</p>${d.files.map(f=>`<p>▧ ${E(f.name)} · ${Math.ceil(f.size/1024)} KB · ${f.data?'<img class="ad-import-thumb" src="'+E(f.data)+'" alt="'+E(f.name)+'">':'需重新选择原图（仅保存文件信息）'}</p>`).join('')}<div class="cm-notice">本轮停在待解析状态。页面排序、切格、OCR 与说话人校正在第03轮；不会用预置故事冒充解析结果。</div><p>原图采用小文件本机保存；超过限制时明确要求重连。原图和识别结果分开。</p>${link('返回项目',`/app/projects/${c.p.id}`,'cm-button ghost')}</section>`;}
  C.adaptationStory=c=>c.c.kind!=='episode'?C.originalStory(c):`<section class="cm-panel"><span class="cm-kicker">EPISODE SCRIPT</span><h2>这一集，直接从文字开始。</h2><p>这是本集独立故事。保存与整理镜头不修改任何漫画章节。</p><label class="cm-label">本集内容<textarea rows="10" data-adapt-input="script">${E(c.e.scriptDraft??c.e.script)}</textarea></label>${B('保存本集内容','save-script')}${B('从故事追加镜头草案','draft')}<p class="cm-help">本机按句整理可编辑草案，不调用模型；每批最多24句，按范围续接；已整理内容不重复追加，原文与候选保留。</p>${link('进入镜头方案 →',path(c,'boards'),'cm-button primary')}</section>`;
  C.adaptationBoards=c=>{
    if(c.e.importDraft)return importPending(c);
    if(c.c.kind!=='episode'){let i=0;return rangeNotice(c)+C.comicBoards(c).replaceAll('</blockquote>',()=>{const b=c.e.boards[i++],matches=(c.p.episodes||[]).flatMap(ep=>P.shots(M.ensure(c.p,ep)).filter(s=>s.sources.some(r=>r.chapterId===c.c.id&&r.panelId===b.id)).map(s=>({ep,s})));return '</blockquote><div class="ad-origin">'+matches.map(({ep,s})=>link(E(ep.title)+' · 定位动画镜头',path({p:c.p,c:ep},'boards','flow')+'&shot='+s.id,'cm-text-link')).join('<br>')+'</div>';});}
    const ss=P.shots(c.e),sources=c.p.chapters.flatMap(ch=>M.ensure(c.p,ch).boards.map((b,i)=>({ch,b,i}))),pending=ss.filter(s=>A.differences(c,s).length);
    return `<div class="cm-stage-toolbar"><div><span class="cm-kicker">EDITABLE ADAPTATION PLAN</span><h2>${sources.length?'漫画与动画，分别创作。':'本集独立镜头方案'}</h2><p>左边是漫画来源，右边是动画播放顺序。修改动画不会写回漫画。</p></div><div>${B('从本集内容追加草案','draft')}${B('＋ 无来源过渡镜','add')}</div></div>${pending.length?`<div class="cm-notice">${pending.length} 个镜头的漫画来源已变化。逐镜比较后，可选择同步、保留改编或解除关联。</div>`:''}<div class="ad-plan"><aside class="cm-panel ad-sources"><h3>漫画来源 · ${sources.length} 格</h3><p class="cm-help">调整漫画阅读顺序不会重排右侧镜头。</p>${sources.map(({ch,b,i})=>{const linked=ss.filter(s=>s.sources.some(r=>r.chapterId===ch.id&&r.panelId===b.id));return `<article class="ad-source" id="ad-source-${b.id}">${(C.comicBaseImage?.(b)||art(b.art,b.title))}<div><small>${E(ch.title)} · 第 ${i+1} 格 · v${b.version}</small><strong>${E(b.title)}</strong><p>${E(b.action)}</p>${link('编辑原漫画 ↗',path({p:c.p,c:ch},'boards')+'&panel='+b.id,'cm-text-link')}<div>${linked.map(s=>B('定位镜头 '+(ss.indexOf(s)+1),'locate-shot',`data-id="${s.id}"`,'cm-text-link')).join('')||'<small>尚未关联镜头</small>'}</div></div></article>`;}).join('')||'<p>本集从文字直接制作，无需漫画成品。</p>'}</aside><section class="ad-shots"><div class="cm-panel"><h3>动画镜头 · ${ss.length} 镜 / ${ss.reduce((n,s)=>n+s.duration,0)} 秒</h3><p>勾选多个镜头合并。第一镜保留原 ID 与采用版，其余镜头归档可找回；合并后的新输入仍需重新生成候选。</p>${B('合并勾选镜头','merge')}</div>${ss.map((s,i)=>`<article class="cm-panel ad-shot" id="ad-shot-${s.id}"><header><label><input type="checkbox" data-adapt-select="${s.id}"> 镜头 ${i+1}</label><small>${s.adoptedId?'已采用 · 输入更改保留旧版':'未采用'} · ${s.candidates.length} 候选</small></header><div class="ad-shot-main">${(C.comicShotImage?.(s)||art(s.art,s.title))}<div><h3>${E(s.title)}</h3><p>${E(s.intent)}</p><blockquote>${E(s.dialogue)}</blockquote><small>${s.duration} 秒 · 镜头输入 v${s.version}</small><div class="ad-origin">${sourceLinks(c,s)}</div></div></div>${A.differences(c,s).length?B('来源已变化 · 比较','diff',`data-id="${s.id}"`,'cm-button primary small'):''}<footer>${B('编辑镜头','edit',`data-id="${s.id}"`)}${B('一镜拆两镜','split',`data-id="${s.id}"`)}${B('选择来源 / 多格合镜','bind',`data-id="${s.id}"`)}${B('↑','move',`data-id="${s.id}" data-dir="-1" aria-label="上移镜头 ${i+1}" ${i===0?'disabled':''}`)}${B('↓','move',`data-id="${s.id}" data-dir="1" aria-label="下移镜头 ${i+1}" ${i===ss.length-1?'disabled':''}`)}${B('移除到归档','remove',`data-id="${s.id}"`)}${B('生成与候选 ↗','motion',`data-id="${s.id}"`)}</footer></article>`).join('')}<section class="cm-panel"><h3>下一步，由你决定</h3><p>当前方案是流程和画布共用的镜头数据。逐步编辑或批量制作都从这里继续。</p>${link('继续逐镜制作 →',path(c,'motion'),'cm-button primary')}${B('按方案批量制作示例','batch')}<details><summary>已归档镜头 ${c.e.archivedShots.length}</summary>${c.e.archivedShots.map(s=>`<p>${E(s.title)} · ${s.candidates.length} 候选 ${B('找回','restore',`data-id="${s.id}"`)}</p>`).join('')}</details></section></section></div>`;
  };
  const oldStudio=C.studio;C.studio=c=>{
    let html=oldStudio(c);if(c.c.kind==='episode')html=html.replaceAll('分镜与草图','镜头与改编方案').replace('故事与章节','本集内容');
    else html=`<div class="ad-chapter-tools"><span>漫画是独立成品，随时可以改编为动画。</span>${B('改编为动画 ↗','adapt')}</div>`+html;
    if(c.e.importDraft)html=importPending(c);else if(c.c.kind==='episode')html=rangeNotice(c)+html;return html;
  };
  const oldMotion=C.productionMotion;C.productionMotion=c=>`<div class="ad-chapter-tools">${link('← 编辑镜头与来源方案',path(c,'boards'),'cm-text-link')}${P.shots(c.e).some(s=>A.differences(c,s).length)?'<span>漫画来源有更新，采用版仍保留；请回方案比较。</span>':''}</div>`+oldMotion(c);
  let comparedRoute='';const oldAfter=C.afterRender;C.afterRender=route=>{oldAfter(route);const sid=route.params.get('shot');if(sid){S.$('#ad-shot-'+sid)?.scrollIntoView({block:'center'});S.$('#ad-shot-'+sid)?.classList.add('ad-highlight');const key=route.path+'?'+route.params.toString();if(route.params.get('compare')&&comparedRoute!==key){comparedRoute=key;const c=C.ctx(),s=P.find(c,sid);if(s&&A.differences(c,s).length)diff(c,s);}}if(!route.params.get('compare'))comparedRoute='';const pid=route.params.get('panel');if(pid&&C.ctx().c.kind!=='episode'){const i=C.ctx().e.boards.findIndex(b=>b.id===pid);if(i>=0){C.ui.selectedBoard=i;S.$$('.cm-board')[i]?.scrollIntoView({block:'center'});S.$$('.cm-board')[i]?.classList.add('ad-highlight');}}};
  C.pages.new=ctx=>{
    const d=M.db.newDraft??={name:'',text:'',source:ctx.params.get('source')||'idea',output:ctx.params.get('output')||'comic',view:'flow',tone:'细腻治愈',candidate:''};
    if(ctx.params.get('source'))d.source=ctx.params.get('source');if(ctx.params.get('output'))d.output=ctx.params.get('output');
    const upload=d.source==='comic';return `<div class="cm-page-heading"><div><span class="cm-kicker">YOUR NEXT WORK</span><h1>先选来源，再决定作品。</h1><p>文字可以直接成为漫画或视频；首次选择只决定默认入口，项目里随时新增另一种作品。</p></div></div><div class="cm-new-layout"><section class="cm-panel"><h2>1. 输入来源</h2><div class="cm-source-tabs">${[['idea','文字 / 灵感'],['script','已有故事 / 分场内容'],['comic','上传漫画']].map(([v,t])=>B(t,'source',`data-value="${v}"`,d.source===v?'cm-button primary':'cm-button ghost')).join('')}</div><label class="cm-label">作品名称<input data-adapt-draft="name" value="${E(d.name||'')}"></label>${upload?`<label class="cm-upload">选择漫画图片<input type="file" accept="image/*" multiple data-adapt-upload><small>无需填写故事文本。单张 ≤ 700KB、合计 ≤ 1.5MB 可保存本机原图；超过时保存清单并要求重连。</small></label><p id="ad-upload-status">${(d.files||[]).map(f=>E(f.name)+(f.data?' · 本机已保存':' · 待重连')).join('<br>')||'尚未选择图片'}</p><div class="cm-notice">创建后进入待解析草稿，不会直接生成虚构分格。完整解析与校正留第03轮。</div>`:`<label class="cm-label">故事文字<textarea rows="9" data-adapt-draft="text" placeholder="女孩回到书店。看到桌上信件。犹豫。拿起信。听见门响。回头。">${E(d.text||'')}</textarea></label><p class="cm-help">先整理为可编辑方案，再按方案逐步或批量制作。当前按句整理为本机示例；首次最多整理24句，超过部分明确显示剩余，可继续整理。</p>`}</section><section class="cm-panel"><h2>2. 目标作品</h2><label class="cm-label">默认目标<select data-adapt-draft="output"><option value="comic" ${d.output==='comic'?'selected':''}>${upload?'漫画整理草稿':'漫画 · 独立成品'}</option><option value="motion" ${d.output==='motion'?'selected':''}>${upload?'漫画 → 视频':'视频 · 直接从文字开始'}</option></select></label><p>漫画分格与动画镜头各自保存；改编关联可以拆镜、合镜、补镜，来源更新由你选择同步。</p>${d.candidate&&!upload?`<details><summary>保留的故事候选（可选择使用）</summary><p>${E(d.candidate)}</p>${B('使用此候选作为文字','use-candidate')}</details>`:''}<div class="cm-new-submit">${B(upload?'创建漫画待解析草稿 →':'建立工程与可编辑方案 →','create','','cm-button primary full')}${B('从空白无限画布开始','blank','','cm-text-link')}</div><p class="cm-help">流程与无限画布是同一工程的两种视图，可随时切换。视频与模型费用仍为模拟。</p></section></div>`;
  };
  function edit(c,s){S.modal('编辑动画镜头 · 不修改漫画',`<form data-adapt-form="shot" data-id="${s.id}"><label class="cm-label">镜头标题<input name="title" required value="${E(s.title)}"></label><label class="cm-label">剧情意图<textarea name="intent" rows="4" required>${E(s.intent)}</textarea></label><label class="cm-label">对白<textarea name="dialogue">${E(s.dialogue)}</textarea></label><label class="cm-label">时长（秒）<input name="duration" type="number" min="4" max="30" value="${s.duration}"></label><p>${E(refsText(c,s))}</p><p class="cm-help">保存输入后，原候选和采用版继续保留。</p><button class="cm-button primary">保存镜头方案</button></form>`,B('取消','close'));}
  function diff(c,s){const changes=A.differences(c,s);const side=(b,title)=>`<section><h3>${title}</h3>${b?(C.comicBaseImage?.(b)||art(b.art,b.title))+`<strong>${E(b.title)} · ${E(b.shot||'')}</strong><p>${E(b.action)}</p><blockquote>${E(b.dialogue)}</blockquote>${C.comicSourceDetails?C.comicSourceDetails(b):''}`:'<p>来源已移除，请保留改编或解除关联</p>'}</section>`;S.modal('来源变化比较 · '+s.title,`<p>当前动画意图：${E(s.intent)}</p>${changes.map(d=>`<div class="ad-diff">${side(d.ref.snapshot,'已引用 v'+d.ref.version)}${side(d.b,d.b?'漫画当前 v'+d.b.version:'来源已移除')}</div>`).join('')}<p>同步会按全部关联分格重建镜头标题、意图、对白和画面参考；时长、候选、旧采用版与交付快照保留。</p>`,B('取消','close')+B('保留当前改编','resolve',`data-id="${s.id}" data-mode="keep"`)+B('解除来源关联','resolve',`data-id="${s.id}" data-mode="detach"`)+B('选择同步来源','resolve',`data-id="${s.id}" data-mode="update" ${changes.some(d=>!d.b)?'disabled':''}`,'cm-button primary'),true);}
  function batch(c){const ss=P.shots(c.e).filter(s=>!s.adoptedId),cost=ss.length*.4;C.ui.adBatch={project:c.p.id,unit:c.c.id,shots:ss.map(s=>({id:s.id,version:s.version})),revision:c.e.planRevision||0};S.modal('按当前方案批量制作',`<p>范围：${ss.length} 个未采用镜头；已采用镜头跳过。每镜保存一个待采用候选，不自动覆盖。</p><p>本次模拟 ${money(cost)} / 剩余 ${money(c.e.budget-c.e.spent)}。</p><p>预算不足或输入已变更时整批停止；本机同步演示，无后台收费任务。生成完停在候选，审阅采用后才能交付。</p>`,B('取消并继续编辑','close')+B('确认批量制作示例','confirm-batch',cost>c.e.budget-c.e.spent||!ss.length?'disabled':'','cm-button primary'));}
  document.addEventListener('click',ev=>{
    const legacy=ev.target.closest('[data-cm="enable-motion"],[data-prod="new-episode"],[data-cm="run-plan"]');
    if(legacy){const c=C.ctx();if(legacy.dataset.cm==='enable-motion'){ev.preventDefault();ev.stopImmediatePropagation();if(!editable(c))return;const ep=P.addEpisode(c.p,c.c.title+' · 动画改编',[c.c.id]);M.activate(c.p.id,ep.id);S.route(path(M.context(c.p.id,ep.id),'boards'));return;}if(legacy.dataset.cm==='run-plan'&&c.c.kind==='episode'){ev.preventDefault();ev.stopImmediatePropagation();batch(c);return;}}
    const el=ev.target.closest('[data-adapt]');if(!el)return;ev.preventDefault();ev.stopImmediatePropagation();const action=el.dataset.adapt,c=C.ctx(),s=c&&P.find(c,el.dataset.id);
    if(action==='close'){S.close();return;}
    if(action==='source'){M.db.newDraft.source=el.dataset.value;M.save();repaint();return;}
    if(action==='use-candidate'){M.db.newDraft.text=M.db.newDraft.candidate;M.save();repaint();return;}
    if(action==='create'||action==='blank'){const d=M.db.newDraft;if(d.source==='comic'&&!d.files?.length){S.toast('请先选择漫画图片');return;}if(action==='create'&&d.source!=='comic'&&!d.text?.trim()){S.toast('请先写下故事文字');return;}const cc=A.create({...d,view:action==='blank'?'canvas':'flow',blank:action==='blank'});if(cc.e.importDraft)cc.e.importDraft.target=d.output;M.db.newDraft=null;M.remember(cc);M.save();S.route(path(cc,cc.e.stage,cc.e.view));return;}
    if(action==='locate-shot'){S.$('#ad-shot-'+el.dataset.id)?.scrollIntoView({block:'center'});S.$('#ad-shot-'+el.dataset.id)?.classList.add('ad-highlight');return;}
    if(action==='motion'){c.e.selectedShotId=s.id;M.save();S.route(path(c,'motion'));return;}
    if(!editable(c))return;
    switch(action){
      case'adapt':{if(c.e.importDraft){S.toast('漫画尚待解析，不能编造改编镜头');return;}const ep=P.addEpisode(c.p,c.c.title+' · 动画改编',[c.c.id]);const cc=M.activate(c.p.id,ep.id);S.route(path(cc,'boards'));return;}
      case'add':A.add(c);repaint();return;
      case'edit':edit(c,s);return;
      case'split':A.split(c,s.id);repaint();return;
      case'move':{const ss=P.shots(c.e),i=ss.indexOf(s),j=i+Number(el.dataset.dir);if(j<0||j>=ss.length)return;[ss[i],ss[j]]=[ss[j],ss[i]];c.e.planRevision=(c.e.planRevision||0)+1;c.e.reviewChecks=[false,false,false];M.save();repaint();return;}
      case'merge':{const ids=S.$$('[data-adapt-select]:checked').map(x=>x.dataset.adaptSelect);if(ids.length<2){S.toast('先勾选至少两个镜头');return;}A.merge(c,ids);repaint();return;}
      case'remove':S.modal('移除镜头到归档',`<p>${E(s.title)} 的 ${s.candidates.length} 个候选与采用版会保留在归档中，可随时找回。当前播放序列将移除此镜头。</p>`,B('取消','close')+B('移除并归档','confirm-remove',`data-id="${s.id}"`));return;
      case'confirm-remove':A.remove(c,s.id);S.close();repaint();return;
      case'restore':A.restore(c,el.dataset.id);repaint();return;
      case'diff':diff(c,s);return;
      case'resolve':{const error=A.resolve(c,s.id,el.dataset.mode);if(error){S.toast(error);return;}S.close();repaint();return;}
      case'bind':S.modal('选择镜头来源 · 支持多格合镜',`<form data-adapt-form="bind" data-id="${s.id}">${c.p.chapters.flatMap(ch=>M.ensure(c.p,ch).boards.map((b,i)=>`<label class="cm-check"><input type="checkbox" name="source" value="${ch.id}|${b.id}" ${s.sources.some(r=>r.chapterId===ch.id&&r.panelId===b.id)?'checked':''}>${E(ch.title)} / 第 ${i+1} 格 · ${E(b.title)} · v${b.version}</label>`)).join('')}<p>可多选，也可全不选成为独立镜头。这里只建立关联，不覆盖当前镜头意图；需要更新时再编辑镜头。</p><button class="cm-button primary">保存来源关系</button></form>`,B('取消','close'));return;
      case'save-script':c.e.script=c.e.scriptDraft??c.e.script;delete c.e.scriptDraft;M.change(c.e,'story','保存本集独立故事');S.navigationScriptSaved?.();repaint();return;
      case'draft':{const r=A.range(c);C.ui.adRange={text:r.text,done:r.done};S.modal('继续整理原文范围',`<p>共 ${r.total} 句，已整理前 ${r.done} 句，剩余 ${r.remaining} 句。</p><p>${r.remaining?'本次仅整理第 '+r.nextStart+'–'+r.nextEnd+' 句；保留已有分格、镜头ID、候选和采用版。':'当前原文已全部整理，不再重复追加。'}</p>${r.remaining?'<blockquote>'+r.lines.slice(r.done,r.nextEnd).map((text,i)=>'第 '+(r.nextStart+i)+' 句：'+E(text)).join('<br>')+'</blockquote>':''}`,B('取消','close')+B('确认续接此范围','confirm-draft',r.remaining?'':'disabled','cm-button primary'));return;}
      case'confirm-draft':{const error=A.draft(c,C.ui.adRange);if(error){S.toast(error);return;}S.close();S.route(path(c,'boards'));repaint();return;}
      case'batch':batch(c);return;
      case'confirm-batch':{const b=C.ui.adBatch,cc=M.context(b.project,b.unit),ss=b.shots.map(x=>P.find(cc,x.id));if(b.revision!==(cc.e.planRevision||0)||ss.some((s,i)=>!s||s.version!==b.shots[i].version||s.adoptedId)){S.toast('方案已变化，请取消后重新确认批次');return;}if(ss.length*.4>cc.e.budget-cc.e.spent){S.toast('预算不足，未生成任何候选');return;}for(const s of ss){const r=P.generate(cc,s.id);if(r.error){S.toast(r.error);return;}}S.close();S.route(path(cc,'motion'));repaint();S.toast('批次示例完成，候选待你逐镜采用');return;}
    }
  },true);
  document.addEventListener('input',ev=>{const el=ev.target;if(el.dataset.adaptDraft){M.db.newDraft[el.dataset.adaptDraft]=el.value;M.save();}if(el.dataset.adaptInput==='script'){C.ctx().e.scriptDraft=el.value;M.save();}});
  document.addEventListener('change',async ev=>{const el=ev.target;if(el.dataset.adaptDraft){M.db.newDraft[el.dataset.adaptDraft]=el.value;M.save();}if(el.hasAttribute('data-adapt-upload')){const draft=M.db.newDraft,files=[...el.files],total=files.reduce((n,f)=>n+f.size,0);try{draft.files=await Promise.all(files.filter(f=>f.type.startsWith('image/')).map(async f=>({name:f.name,size:f.size,type:f.type,data:f.size<=700000&&total<=1500000?await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(f);}):null})));if(M.save()===false){draft.files.forEach(f=>f.data=null);M.save();S.toast('空间不足：仅登记图片清单，原图需重新选择。');}repaint();}catch{S.toast('图片读取失败，请重新选择；既有项目未变更。');}}});
  document.addEventListener('submit',ev=>{const chapter=ev.target.closest('[data-cm-form="add-chapter"]');if(chapter){ev.preventDefault();ev.stopImmediatePropagation();const c=C.ctx();if(!editable(c))return;const cc=A.addChapter(c.p,new FormData(chapter).get('title'));S.navigationSaved?.(chapter,true);S.close();S.route(path(cc,'story'));return;}const f=ev.target.closest('[data-adapt-form]');if(!f)return;ev.preventDefault();ev.stopImmediatePropagation();const c=C.ctx();if(!editable(c))return;const s=P.find(c,f.dataset.id),v=Object.fromEntries(new FormData(f));if(f.dataset.adaptForm==='shot'){Object.assign(s,{title:v.title,intent:v.intent,dialogue:v.dialogue,duration:Math.max(4,Math.min(30,Number(v.duration)||5)),version:s.version+1});c.e.reviewChecks=[false,false,false];c.e.planRevision=(c.e.planRevision||0)+1;M.log(c.e,'保存独立镜头输入','旧候选与采用版保留');}else A.bind(c,s.id,new FormData(f).getAll('source'));M.save();S.navigationSaved?.(f,true);S.close();repaint();},true);
})();
